"""Visual skin layered over the shell in views.page().

Presentation only: extra CSS/JS and decorative chrome. No routes, permissions or data
are decided here; `may` is passed in so navigation mirrors what the top bar already shows.
Animations are on by default and controlled only by the in-app toggle (localStorage
"fr-motion"); the OS reduce-motion setting is intentionally not consulted.
"""
from __future__ import annotations

from collections.abc import Callable

_MOTION_BOOT = (
    '<script>try{if(localStorage.getItem("fr-motion")==="off")'
    'document.documentElement.classList.add("motion-off")}catch(e){}</script>'
)

CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* ===== A · Crosswalk Atlas ===== */\n.top{gap:1.4rem;padding-top:1rem!important;padding-bottom:1rem!important;margin-bottom:1.6rem;\n  box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.35rem;font-weight:700}\n.top h1 a::before{content:"";display:inline-block;width:1.6rem;height:1.6rem;margin-right:.6rem;vertical-align:-.35rem;\n  background:conic-gradient(from 210deg,var(--fw1),var(--fw2),var(--fw3),var(--fw1));border-radius:50%;\n  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);\n  animation:aSpin 14s linear infinite}\n@keyframes aSpin{to{transform:rotate(360deg)}}\n.topnav{font-size:.98rem;padding:.6rem 1.1rem;color:var(--body);position:relative}\n.topnav::after{content:"";position:absolute;left:1.1rem;right:1.1rem;bottom:.3rem;height:2px;border-radius:2px;\n  background:linear-gradient(90deg,var(--fw1),var(--fw2));transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}\n.topnav:hover{background:var(--surface-high)}.topnav:hover::after{transform:scaleX(1)}\n.topright{margin-left:auto}\n.sk-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(1.5rem,3vw,4rem);align-items:center;\n  min-height:min(64vh,640px);margin:0 0 1.5rem}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.6rem}\n.sk-hero .stage-headline{font-size:clamp(2.2rem,4vw,3.6rem);line-height:1.08;letter-spacing:-.035em}\n.sk-hero .stage-sub{margin:0 0 .5rem;max-width:40rem}\n.sk-hero form.seek{margin:0 0 1rem;max-width:none;padding:.5rem .55rem .5rem 1.4rem}\n.sk-hero form.seek input[type=search]{font-size:1.1rem;padding:.85rem .5rem}\n.sk-hero form.seek button{padding:.85rem 1.9rem;font-size:1rem}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0 .6rem}\n.sk-hero .note{text-align:left!important;margin:0}\n.sk-visual{position:relative;height:min(60vh,600px);border-radius:28px;overflow:hidden;\n  background:radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--accent) 12%,var(--surface)),var(--surface) 70%);\n  box-shadow:var(--card-shadow)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-legend{position:absolute;left:1.2rem;bottom:1rem;display:flex;gap:.6rem;flex-wrap:wrap;z-index:2}\n.sk-legend span{font-size:.8rem;font-weight:600;padding:.3rem .75rem;border-radius:980px;background:color-mix(in srgb,var(--surface) 78%,transparent);\n  backdrop-filter:blur(8px);color:var(--ink);display:inline-flex;align-items:center;gap:.45rem}\n.sk-legend i{width:.6rem;height:.6rem;border-radius:50%;display:inline-block}\n.sk-caption{position:absolute;right:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);z-index:2}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:1rem 0 2rem}\n.stat-card{text-align:left;padding:1.6rem 1.6rem;border-radius:22px;position:relative;overflow:hidden}\n.stat-card::before{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:160%;\n  background:radial-gradient(circle,color-mix(in srgb,var(--accent) 14%,transparent),transparent 65%);transition:transform .6s var(--ease)}\n.stat-card:hover::before{transform:translate(-12%,12%)}\n.stat-num{font-size:2.6rem;letter-spacing:-.03em}\n.stat-desc{color:var(--muted);letter-spacing:.1em}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;gap:2rem}\n.cards{grid-template-columns:repeat(auto-fill,minmax(17rem,1fr))}\n.card{border-radius:20px;padding:1.45rem 1.55rem}\n.card:hover{transform:translateY(-4px) rotateX(2deg)}\n.card .id{font-size:.82rem;color:var(--accent)}\n.card h3{font-size:1.1rem}\nh2{font-size:1.5rem}\n.hud-card{border-radius:22px}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n/* login: split */\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{height:min(72vh,680px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}\n.sk-login .auth form{padding:2rem 2rem;border-radius:24px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
HEAD_JS = '(function(){var r=document.documentElement;try{if(!localStorage.getItem("fr-theme")&&matchMedia("(prefers-color-scheme: light)").matches)r.dataset.theme="light"}catch(e){}\nvar light=r.dataset.theme==="light";\nwindow.FR_FW_COLORS=light?{"NIST-CSF-2.0":"#5C7F99","NIST-800-53-R5":"#7E9A7A","ISO-27002-2022":"#B08F55"}:{"NIST-CSF-2.0":"#8FB0C6","NIST-800-53-R5":"#9DB89A","ISO-27002-2022":"#CDB487"};\nwindow.FR_ACCENT=light?"#3F7D62":"#7DBA98";})();\n'
TAIL_JS = '(function(){\nvar R=document.documentElement;function motion(){return !R.classList.contains(\'motion-off\')}\nwindow.FR_motion=motion;\n// recolor graph chips to calm palette\ndocument.querySelectorAll(\'.framework-chips .chip[data-fid]\').forEach(function(c){var col=(window.FR_FW_COLORS||{})[c.dataset.fid];if(col){c.style.color=col;var d=c.querySelector(\'.chip-dot\');if(d)d.style.background=col}});\n// stagger groups\ndocument.querySelectorAll(\'.stage-stats,.cards,.hud-stat-list\').forEach(function(g){g.classList.add(\'sk-stagger\');Array.from(g.children).forEach(function(c,i){c.style.setProperty(\'--i\',i)})});\n// count-up\ndocument.querySelectorAll(\'.stat-num\').forEach(function(el){var m=el.textContent.match(/^([\\d,]+)(.*)$/);if(!m||!motion())return;var to=parseInt(m[1].replace(/,/g,\'\'),10),suf=m[2],t0=null;\n function f(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString(\'en-US\')+suf;if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});\n// shared canvas helper\nwindow.FR_canvas=function(cv,draw){var ctx=cv.getContext(\'2d\'),W=0,H=0,dpr=Math.min(2,devicePixelRatio||1),mx=0,my=0,t0=performance.now();\n function size(){var b=cv.getBoundingClientRect();W=b.width;H=b.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}\n size();new ResizeObserver(size).observe(cv);\n addEventListener(\'pointermove\',function(e){var b=cv.getBoundingClientRect();mx=((e.clientX-b.left)/b.width-.5);my=((e.clientY-b.top)/b.height-.5)},{passive:true});\n function css(n){return getComputedStyle(R).getPropertyValue(n).trim()}\n var last=0;function loop(now){var t=motion()?(now-t0)/1000:last;last=t;ctx.clearRect(0,0,W,H);draw(ctx,W,H,t,mx,my,css,R.dataset.theme===\'light\');requestAnimationFrame(loop)}\n requestAnimationFrame(loop)};\n})();\n(function(){\nfunction orbit(cv){var rings=[{n:22,r:.92,tilt:1.15,ph:0,col:\'--fw1\',name:\'CSF\'},{n:40,r:.68,tilt:-.95,ph:1.7,col:\'--fw2\',name:\'800-53\'},{n:30,r:.44,tilt:.55,ph:3.1,col:\'--fw3\',name:\'ISO\'}];\n var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647}\n var links=[];for(var i=0;i<46;i++){var a=Math.floor(rnd()*3),b=(a+1+Math.floor(rnd()*2))%3;links.push([a,Math.floor(rnd()*rings[a].n),b,Math.floor(rnd()*rings[b].n),rnd()])}\n FR_canvas(cv,function(c,W,H,t,mx,my,css,light){var S=Math.min(W,H)*.46,cx=W/2+mx*18,cy=H/2+my*14,ry=t*.18+mx*.6,rx=-.35+my*.4;\n  function P(ring,k){var R=rings[ring],a=k/R.n*Math.PI*2+R.ph+t*.05*(ring%2?-1:1),x=Math.cos(a)*R.r,y=0,z=Math.sin(a)*R.r;\n   var ct=Math.cos(R.tilt),st=Math.sin(R.tilt);var y2=y*ct-z*st,z2=y*st+z*ct;y=y2;z=z2;\n   var cr=Math.cos(ry),sr=Math.sin(ry);var x3=x*cr+z*sr,z3=-x*sr+z*cr;var cxr=Math.cos(rx),sxr=Math.sin(rx);var y4=y*cxr-z3*sxr,z4=y*sxr+z3*cxr;\n   var p=2.6/(2.6+z4);return {x:cx+x3*S*p,y:cy+y4*S*p,z:z4,p:p}}\n  var cols=rings.map(function(r){return css(r.col)});\n  // core glow\n  var g=c.createRadialGradient(cx,cy,0,cx,cy,S*.5);g.addColorStop(0,light?\'rgba(63,125,98,.22)\':\'rgba(125,186,152,.22)\');g.addColorStop(1,\'rgba(0,0,0,0)\');c.fillStyle=g;c.fillRect(0,0,W,H);\n  // ring paths\n  rings.forEach(function(R,ri){c.beginPath();for(var k=0;k<=72;k++){var q=P(ri,k/72*R.n);k?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y)}c.strokeStyle=cols[ri];c.globalAlpha=.22;c.lineWidth=1.2;c.stroke();c.globalAlpha=1});\n  // links + pulses\n  links.forEach(function(L){var a=P(L[0],L[1]),b=P(L[2],L[3]);var mxp=(a.x+b.x)/2+(cx-(a.x+b.x)/2)*.45,myp=(a.y+b.y)/2+(cy-(a.y+b.y)/2)*.45;\n   c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo(mxp,myp,b.x,b.y);c.strokeStyle=cols[L[0]];c.globalAlpha=.16;c.lineWidth=1;c.stroke();\n   var u=(t*.22+L[4])%1,ix=(1-u)*(1-u)*a.x+2*(1-u)*u*mxp+u*u*b.x,iy=(1-u)*(1-u)*a.y+2*(1-u)*u*myp+u*u*b.y;\n   c.globalAlpha=Math.sin(u*Math.PI)*.95;c.fillStyle=cols[L[2]];c.beginPath();c.arc(ix,iy,2.2,0,7);c.fill();c.globalAlpha=1});\n  // nodes depth-sorted\n  var all=[];rings.forEach(function(R,ri){for(var k=0;k<R.n;k++){var q=P(ri,k);q.ri=ri;all.push(q)}});all.sort(function(a,b){return b.z-a.z});\n  all.forEach(function(q){var r=(q.ri==0?3.6:q.ri==1?2.6:3.1)*q.p;c.globalAlpha=.35+.65*Math.max(0,Math.min(1,(1.2-q.z)/2));\n   c.fillStyle=cols[q.ri];c.beginPath();c.arc(q.x,q.y,r,0,7);c.fill();\n   if(q.ri==0){c.strokeStyle=cols[0];c.globalAlpha*=.35;c.beginPath();c.arc(q.x,q.y,r*2.2,0,7);c.stroke()}c.globalAlpha=1});\n })}\nwindow.FR_orbit=orbit;\nfunction visual(cap){var v=document.createElement(\'div\');v.className=\'sk-visual\';v.innerHTML=\'<canvas aria-hidden="true"></canvas><div class="sk-caption">\'+cap+\'</div><div class="sk-legend"><span><i style="background:var(--fw1)"></i>NIST CSF 2.0</span><span><i style="background:var(--fw2)"></i>SP 800-53 Rev.5</span><span><i style="background:var(--fw3)"></i>ISO/IEC 27002</span></div>\';return v}\nvar hero=document.querySelector(\'.pagein > .stage-hero\');\nif(hero){var box=document.createElement(\'section\');box.className=\'sk-hero\';var left=document.createElement(\'div\');left.className=\'sk-stagger\';\n hero.parentNode.insertBefore(box,hero);[hero,hero.parentNode.querySelector(\'form.seek\'),hero.parentNode.querySelector(\'.quick-chips\'),box.nextElementSibling&&box.parentNode.querySelector(\':scope > p.note\')].forEach(function(e,i){if(e){e.style.setProperty(\'--i\',i);left.appendChild(e)}});\n var v=visual(\'Official crosswalk · live\');box.appendChild(left);box.appendChild(v);orbit(v.querySelector(\'canvas\'))}\nvar auth=document.querySelector(\'.pagein > .auth\');\nif(auth){var lg=document.createElement(\'section\');lg.className=\'sk-login\';auth.parentNode.insertBefore(lg,auth);var v2=visual(\'Framework Reader\');lg.appendChild(v2);lg.appendChild(auth);orbit(v2.querySelector(\'canvas\'))}\n})();\n'


def head() -> str:
    return _MOTION_BOOT + (f"<script>{HEAD_JS}</script>" if HEAD_JS else "")


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    return ""


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* ===== A · Crosswalk Atlas ===== */\n.top{gap:1.4rem;padding-top:1rem!important;padding-bottom:1rem!important;margin-bottom:1.6rem;\n  box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.35rem;font-weight:700}\n.top h1 a::before{content:"";display:inline-block;width:1.6rem;height:1.6rem;margin-right:.6rem;vertical-align:-.35rem;\n  background:conic-gradient(from 210deg,var(--fw1),var(--fw2),var(--fw3),var(--fw1));border-radius:50%;\n  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);\n  animation:aSpin 14s linear infinite}\n@keyframes aSpin{to{transform:rotate(360deg)}}\n.topnav{font-size:.98rem;padding:.6rem 1.1rem;color:var(--body);position:relative}\n.topnav::after{content:"";position:absolute;left:1.1rem;right:1.1rem;bottom:.3rem;height:2px;border-radius:2px;\n  background:linear-gradient(90deg,var(--fw1),var(--fw2));transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}\n.topnav:hover{background:var(--surface-high)}.topnav:hover::after{transform:scaleX(1)}\n.topright{margin-left:auto}\n.sk-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(1.5rem,3vw,4rem);align-items:center;\n  min-height:min(64vh,640px);margin:0 0 1.5rem}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.6rem}\n.sk-hero .stage-headline{font-size:clamp(2.2rem,4vw,3.6rem);line-height:1.08;letter-spacing:-.035em}\n.sk-hero .stage-sub{margin:0 0 .5rem;max-width:40rem}\n.sk-hero form.seek{margin:0 0 1rem;max-width:none;padding:.5rem .55rem .5rem 1.4rem}\n.sk-hero form.seek input[type=search]{font-size:1.1rem;padding:.85rem .5rem}\n.sk-hero form.seek button{padding:.85rem 1.9rem;font-size:1rem}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0 .6rem}\n.sk-hero .note{text-align:left!important;margin:0}\n.sk-visual{position:relative;height:min(60vh,600px);border-radius:28px;overflow:hidden;\n  background:radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--accent) 12%,var(--surface)),var(--surface) 70%);\n  box-shadow:var(--card-shadow)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-legend{position:absolute;left:1.2rem;bottom:1rem;display:flex;gap:.6rem;flex-wrap:wrap;z-index:2}\n.sk-legend span{font-size:.8rem;font-weight:600;padding:.3rem .75rem;border-radius:980px;background:color-mix(in srgb,var(--surface) 78%,transparent);\n  backdrop-filter:blur(8px);color:var(--ink);display:inline-flex;align-items:center;gap:.45rem}\n.sk-legend i{width:.6rem;height:.6rem;border-radius:50%;display:inline-block}\n.sk-caption{position:absolute;right:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);z-index:2}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:1rem 0 2rem}\n.stat-card{text-align:left;padding:1.6rem 1.6rem;border-radius:22px;position:relative;overflow:hidden}\n.stat-card::before{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:160%;\n  background:radial-gradient(circle,color-mix(in srgb,var(--accent) 8%,transparent),transparent 65%);transition:transform .6s var(--ease)}\n.stat-card:hover::before{transform:translate(-12%,12%)}\n.stat-num{font-size:2.6rem;letter-spacing:-.03em}\n.stat-desc{color:var(--muted);letter-spacing:.1em}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;gap:2rem}\n.cards{grid-template-columns:repeat(auto-fill,minmax(17rem,1fr))}\n.card{border-radius:20px;padding:1.45rem 1.55rem}\n.card:hover{transform:translateY(-4px) rotateX(2deg)}\n.card .id{font-size:.82rem;color:var(--accent)}\n.card h3{font-size:1.1rem}\nh2{font-size:1.5rem}\n.hud-card{border-radius:22px}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n/* login: split */\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{height:min(72vh,680px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}\n.sk-login .auth form{padding:2rem 2rem;border-radius:24px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
HEAD_JS = '(function(){var r=document.documentElement;try{if(!localStorage.getItem("fr-theme")&&matchMedia("(prefers-color-scheme: light)").matches)r.dataset.theme="light"}catch(e){}\nvar light=r.dataset.theme==="light";\nwindow.FR_FW_COLORS=light?{"NIST-CSF-2.0":"#5C7F99","NIST-800-53-R5":"#7E9A7A","ISO-27002-2022":"#B08F55"}:{"NIST-CSF-2.0":"#8FB0C6","NIST-800-53-R5":"#9DB89A","ISO-27002-2022":"#CDB487"};\nwindow.FR_ACCENT=light?"#3F7D62":"#7DBA98";})();\n'
TAIL_JS = '(function(){\nvar R=document.documentElement;function motion(){return !R.classList.contains(\'motion-off\')}\nwindow.FR_motion=motion;\n// recolor graph chips to calm palette\ndocument.querySelectorAll(\'.framework-chips .chip[data-fid]\').forEach(function(c){var col=(window.FR_FW_COLORS||{})[c.dataset.fid];if(col){c.style.color=col;var d=c.querySelector(\'.chip-dot\');if(d)d.style.background=col}});\n// stagger groups\ndocument.querySelectorAll(\'.stage-stats,.cards,.hud-stat-list\').forEach(function(g){g.classList.add(\'sk-stagger\');Array.from(g.children).forEach(function(c,i){c.style.setProperty(\'--i\',i)})});\n// count-up\ndocument.querySelectorAll(\'.stat-num\').forEach(function(el){var m=el.textContent.match(/^([\\d,]+)(.*)$/);if(!m||!motion())return;var to=parseInt(m[1].replace(/,/g,\'\'),10),suf=m[2],t0=null;\n function f(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString(\'en-US\')+suf;if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});\n// shared canvas helper\nwindow.FR_canvas=function(cv,draw){var ctx=cv.getContext(\'2d\'),W=0,H=0,dpr=Math.min(2,devicePixelRatio||1),mx=0,my=0,t0=performance.now();\n function size(){var b=cv.getBoundingClientRect();W=b.width;H=b.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}\n size();new ResizeObserver(size).observe(cv);\n addEventListener(\'pointermove\',function(e){var b=cv.getBoundingClientRect();mx=((e.clientX-b.left)/b.width-.5);my=((e.clientY-b.top)/b.height-.5)},{passive:true});\n function css(n){return getComputedStyle(R).getPropertyValue(n).trim()}\n var last=0;function loop(now){var t=motion()?(now-t0)/1000:last;last=t;ctx.clearRect(0,0,W,H);draw(ctx,W,H,t,mx,my,css,R.dataset.theme===\'light\');requestAnimationFrame(loop)}\n requestAnimationFrame(loop)};\n})();\n(function(){\nfunction orbit(cv){var rings=[{n:22,r:.92,tilt:1.2,roll:0,ph:0,col:\'--fw1\',name:\'CSF\'},{n:40,r:.7,tilt:1.1,roll:1.05,ph:1.7,col:\'--fw2\',name:\'800-53\'},{n:30,r:.48,tilt:1.0,roll:-1.05,ph:3.1,col:\'--fw3\',name:\'ISO\'}];\n var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647}\n var links=[];for(var i=0;i<46;i++){var a=Math.floor(rnd()*3),b=(a+1+Math.floor(rnd()*2))%3;links.push([a,Math.floor(rnd()*rings[a].n),b,Math.floor(rnd()*rings[b].n),rnd()])}\n FR_canvas(cv,function(c,W,H,t,mx,my,css,light){var S=Math.min(W,H)*.46,cx=W/2+mx*18,cy=H/2+my*14,ry=t*.18+mx*.6,rx=-.35+my*.4;\n  function P(ring,k){var R=rings[ring],a=k/R.n*Math.PI*2+R.ph+t*.05*(ring%2?-1:1),x=Math.cos(a)*R.r,y=0,z=Math.sin(a)*R.r;\n   var ct=Math.cos(R.tilt),st=Math.sin(R.tilt);var y2=y*ct-z*st,z2=y*st+z*ct;y=y2;z=z2;var c0=Math.cos(R.roll),s0=Math.sin(R.roll),xr=x*c0-y*s0;y=x*s0+y*c0;x=xr;\n   var cr=Math.cos(ry),sr=Math.sin(ry);var x3=x*cr+z*sr,z3=-x*sr+z*cr;var cxr=Math.cos(rx),sxr=Math.sin(rx);var y4=y*cxr-z3*sxr,z4=y*sxr+z3*cxr;\n   var p=2.6/(2.6+z4);return {x:cx+x3*S*p,y:cy+y4*S*p,z:z4,p:p}}\n  var cols=rings.map(function(r){return css(r.col)});\n  // core glow\n  var g=c.createRadialGradient(cx,cy,0,cx,cy,S*.5);g.addColorStop(0,light?\'rgba(63,125,98,.22)\':\'rgba(125,186,152,.22)\');g.addColorStop(1,\'rgba(0,0,0,0)\');c.fillStyle=g;c.fillRect(0,0,W,H);\n  // ring paths\n  rings.forEach(function(R,ri){c.beginPath();for(var k=0;k<=72;k++){var q=P(ri,k/72*R.n);k?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y)}c.strokeStyle=cols[ri];c.globalAlpha=.22;c.lineWidth=1.2;c.stroke();c.globalAlpha=1});\n  // links + pulses\n  links.forEach(function(L){var a=P(L[0],L[1]),b=P(L[2],L[3]);var mxp=(a.x+b.x)/2+(cx-(a.x+b.x)/2)*.45,myp=(a.y+b.y)/2+(cy-(a.y+b.y)/2)*.45;\n   c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo(mxp,myp,b.x,b.y);c.strokeStyle=cols[L[0]];c.globalAlpha=.16;c.lineWidth=1;c.stroke();\n   var u=(t*.22+L[4])%1,ix=(1-u)*(1-u)*a.x+2*(1-u)*u*mxp+u*u*b.x,iy=(1-u)*(1-u)*a.y+2*(1-u)*u*myp+u*u*b.y;\n   c.globalAlpha=Math.sin(u*Math.PI)*.95;c.fillStyle=cols[L[2]];c.beginPath();c.arc(ix,iy,2.2,0,7);c.fill();c.globalAlpha=1});\n  // nodes depth-sorted\n  var all=[];rings.forEach(function(R,ri){for(var k=0;k<R.n;k++){var q=P(ri,k);q.ri=ri;all.push(q)}});all.sort(function(a,b){return b.z-a.z});\n  all.forEach(function(q){var r=(q.ri==0?3.6:q.ri==1?2.6:3.1)*q.p;c.globalAlpha=.35+.65*Math.max(0,Math.min(1,(1.2-q.z)/2));\n   c.fillStyle=cols[q.ri];c.beginPath();c.arc(q.x,q.y,r,0,7);c.fill();\n   if(q.ri==0){c.strokeStyle=cols[0];c.globalAlpha*=.35;c.beginPath();c.arc(q.x,q.y,r*2.2,0,7);c.stroke()}c.globalAlpha=1});\n })}\nwindow.FR_orbit=orbit;\nfunction visual(cap){var v=document.createElement(\'div\');v.className=\'sk-visual\';v.innerHTML=\'<canvas aria-hidden="true"></canvas><div class="sk-caption">\'+cap+\'</div><div class="sk-legend"><span><i style="background:var(--fw1)"></i>NIST CSF 2.0</span><span><i style="background:var(--fw2)"></i>SP 800-53 Rev.5</span><span><i style="background:var(--fw3)"></i>ISO/IEC 27002</span></div>\';return v}\nvar hero=document.querySelector(\'.pagein > .stage-hero\');\nif(hero){var box=document.createElement(\'section\');box.className=\'sk-hero\';var left=document.createElement(\'div\');left.className=\'sk-stagger\';\n hero.parentNode.insertBefore(box,hero);[hero,hero.parentNode.querySelector(\'form.seek\'),hero.parentNode.querySelector(\'.quick-chips\'),box.nextElementSibling&&box.parentNode.querySelector(\':scope > p.note\')].forEach(function(e,i){if(e){e.style.setProperty(\'--i\',i);left.appendChild(e)}});\n var v=visual(\'Official crosswalk · live\');box.appendChild(left);box.appendChild(v);orbit(v.querySelector(\'canvas\'))}\nvar auth=document.querySelector(\'.pagein > .auth\');\nif(auth){var lg=document.createElement(\'section\');lg.className=\'sk-login\';auth.parentNode.insertBefore(lg,auth);var v2=visual(\'Framework Reader\');lg.appendChild(v2);lg.appendChild(auth);orbit(v2.querySelector(\'canvas\'))}\n})();\n'


def head() -> str:
    return _MOTION_BOOT + (f"<script>{HEAD_JS}</script>" if HEAD_JS else "")


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    return ""


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* control page: action cards without colored top bars, wider reading */\n.doing .claim::before,.doing .chat::before{display:none!important}\n.doing .claim,.doing .chat{border-color:transparent!important;border-radius:22px}\n.split{grid-template-columns:minmax(0,1fr) clamp(20rem,24vw,26rem);gap:clamp(1.5rem,3vw,3.5rem)}\n.doc p,.doc ul,.doc ol{max-width:86ch}\n.doing .claim button{border:0!important;color:#fff!important;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 85%,#fff),var(--accent-strong))!important}\n:root:not([data-theme="light"]) .doing .claim button{background:linear-gradient(180deg,#4C8E70,var(--green))!important}\n.graph-viewport{border-color:transparent!important;box-shadow:var(--card-shadow)}\n/* ===== A · Crosswalk Atlas ===== */\n.top{gap:1.4rem;padding-top:1rem!important;padding-bottom:1rem!important;margin-bottom:1.6rem;\n  box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.35rem;font-weight:700}\n.top h1 a::before{content:"";display:inline-block;width:1.6rem;height:1.6rem;margin-right:.6rem;vertical-align:-.35rem;\n  background:conic-gradient(from 210deg,var(--fw1),var(--fw2),var(--fw3),var(--fw1));border-radius:50%;\n  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);\n  animation:aSpin 14s linear infinite}\n@keyframes aSpin{to{transform:rotate(360deg)}}\n.topnav{font-size:.98rem;padding:.6rem 1.1rem;color:var(--body);position:relative}\n.topnav::after{content:"";position:absolute;left:1.1rem;right:1.1rem;bottom:.3rem;height:2px;border-radius:2px;\n  background:linear-gradient(90deg,var(--fw1),var(--fw2));transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}\n.topnav:hover{background:var(--surface-high)}.topnav:hover::after{transform:scaleX(1)}\n.topright{margin-left:auto}\n.sk-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(1.5rem,3vw,4rem);align-items:center;\n  min-height:min(64vh,640px);margin:0 0 1.5rem}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.6rem}\n.sk-hero .stage-headline{font-size:clamp(2.2rem,4vw,3.6rem);line-height:1.08;letter-spacing:-.035em}\n.sk-hero .stage-sub{margin:0 0 .5rem;max-width:40rem}\n.sk-hero form.seek{margin:0 0 1rem;max-width:none;padding:.5rem .55rem .5rem 1.4rem}\n.sk-hero form.seek input[type=search]{font-size:1.1rem;padding:.85rem .5rem}\n.sk-hero form.seek button{padding:.85rem 1.9rem;font-size:1rem}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0 .6rem}\n.sk-hero .note{text-align:left!important;margin:0}\n.sk-visual{position:relative;height:min(60vh,600px);border-radius:28px;overflow:hidden;\n  background:radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--accent) 12%,var(--surface)),var(--surface) 70%);\n  box-shadow:var(--card-shadow)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-legend{position:absolute;left:1.2rem;bottom:1rem;display:flex;gap:.6rem;flex-wrap:wrap;z-index:2}\n.sk-legend span{font-size:.8rem;font-weight:600;padding:.3rem .75rem;border-radius:980px;background:color-mix(in srgb,var(--surface) 78%,transparent);\n  backdrop-filter:blur(8px);color:var(--ink);display:inline-flex;align-items:center;gap:.45rem}\n.sk-legend i{width:.6rem;height:.6rem;border-radius:50%;display:inline-block}\n.sk-caption{position:absolute;right:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);z-index:2}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:1rem 0 2rem}\n.stat-card{text-align:left;padding:1.6rem 1.6rem;border-radius:22px;position:relative;overflow:hidden}\n.stat-card::before{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:160%;\n  background:radial-gradient(circle,color-mix(in srgb,var(--accent) 8%,transparent),transparent 65%);transition:transform .6s var(--ease)}\n.stat-card:hover::before{transform:translate(-12%,12%)}\n.stat-num{font-size:2.6rem;letter-spacing:-.03em}\n.stat-desc{color:var(--muted);letter-spacing:.1em}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;gap:2rem}\n.cards{grid-template-columns:repeat(auto-fill,minmax(17rem,1fr))}\n.card{border-radius:20px;padding:1.45rem 1.55rem}\n.card:hover{transform:translateY(-4px) rotateX(2deg)}\n.card .id{font-size:.82rem;color:var(--accent)}\n.card h3{font-size:1.1rem}\nh2{font-size:1.5rem}\n.hud-card{border-radius:22px}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n/* login: split */\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{height:min(72vh,680px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}\n.sk-login .auth form{padding:2rem 2rem;border-radius:24px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
HEAD_JS = '(function(){var r=document.documentElement;try{if(!localStorage.getItem("fr-theme")&&matchMedia("(prefers-color-scheme: light)").matches)r.dataset.theme="light"}catch(e){}\nvar light=r.dataset.theme==="light";\nwindow.FR_FW_COLORS=light?{"NIST-CSF-2.0":"#5C7F99","NIST-800-53-R5":"#7E9A7A","ISO-27002-2022":"#B08F55"}:{"NIST-CSF-2.0":"#8FB0C6","NIST-800-53-R5":"#9DB89A","ISO-27002-2022":"#CDB487"};\nwindow.FR_ACCENT=light?"#3F7D62":"#7DBA98";})();\n'
TAIL_JS = '(function(){\nvar R=document.documentElement;function motion(){return !R.classList.contains(\'motion-off\')}\nwindow.FR_motion=motion;\n// recolor graph chips to calm palette\ndocument.querySelectorAll(\'.framework-chips .chip[data-fid]\').forEach(function(c){var col=(window.FR_FW_COLORS||{})[c.dataset.fid];if(col){c.style.color=col;var d=c.querySelector(\'.chip-dot\');if(d)d.style.background=col}});\n// stagger groups\ndocument.querySelectorAll(\'.stage-stats,.cards,.hud-stat-list\').forEach(function(g){g.classList.add(\'sk-stagger\');Array.from(g.children).forEach(function(c,i){c.style.setProperty(\'--i\',i)})});\n// count-up\ndocument.querySelectorAll(\'.stat-num\').forEach(function(el){var m=el.textContent.match(/^([\\d,]+)(.*)$/);if(!m||!motion())return;var to=parseInt(m[1].replace(/,/g,\'\'),10),suf=m[2],t0=null;\n function f(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString(\'en-US\')+suf;if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});\n// shared canvas helper\nwindow.FR_canvas=function(cv,draw){var ctx=cv.getContext(\'2d\'),W=0,H=0,dpr=Math.min(2,devicePixelRatio||1),mx=0,my=0,t0=performance.now();\n function size(){var b=cv.getBoundingClientRect();W=b.width;H=b.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}\n size();new ResizeObserver(size).observe(cv);\n addEventListener(\'pointermove\',function(e){var b=cv.getBoundingClientRect();mx=((e.clientX-b.left)/b.width-.5);my=((e.clientY-b.top)/b.height-.5)},{passive:true});\n function css(n){return getComputedStyle(R).getPropertyValue(n).trim()}\n var last=0;function loop(now){var t=motion()?(now-t0)/1000:last;last=t;ctx.clearRect(0,0,W,H);draw(ctx,W,H,t,mx,my,css,R.dataset.theme===\'light\');requestAnimationFrame(loop)}\n requestAnimationFrame(loop)};\n})();\n(function(){\nfunction orbit(cv){var rings=[{n:22,r:.92,tilt:1.2,roll:0,ph:0,col:\'--fw1\',name:\'CSF\'},{n:40,r:.7,tilt:1.1,roll:1.05,ph:1.7,col:\'--fw2\',name:\'800-53\'},{n:30,r:.48,tilt:1.0,roll:-1.05,ph:3.1,col:\'--fw3\',name:\'ISO\'}];\n var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647}\n var links=[];for(var i=0;i<46;i++){var a=Math.floor(rnd()*3),b=(a+1+Math.floor(rnd()*2))%3;links.push([a,Math.floor(rnd()*rings[a].n),b,Math.floor(rnd()*rings[b].n),rnd()])}\n FR_canvas(cv,function(c,W,H,t,mx,my,css,light){var S=Math.min(W,H)*.46,cx=W/2+mx*18,cy=H/2+my*14,ry=t*.18+mx*.6,rx=-.35+my*.4;\n  function P(ring,k){var R=rings[ring],a=k/R.n*Math.PI*2+R.ph+t*.05*(ring%2?-1:1),x=Math.cos(a)*R.r,y=0,z=Math.sin(a)*R.r;\n   var ct=Math.cos(R.tilt),st=Math.sin(R.tilt);var y2=y*ct-z*st,z2=y*st+z*ct;y=y2;z=z2;var c0=Math.cos(R.roll),s0=Math.sin(R.roll),xr=x*c0-y*s0;y=x*s0+y*c0;x=xr;\n   var cr=Math.cos(ry),sr=Math.sin(ry);var x3=x*cr+z*sr,z3=-x*sr+z*cr;var cxr=Math.cos(rx),sxr=Math.sin(rx);var y4=y*cxr-z3*sxr,z4=y*sxr+z3*cxr;\n   var p=2.6/(2.6+z4);return {x:cx+x3*S*p,y:cy+y4*S*p,z:z4,p:p}}\n  var cols=rings.map(function(r){return css(r.col)});\n  // core glow\n  var g=c.createRadialGradient(cx,cy,0,cx,cy,S*.5);g.addColorStop(0,light?\'rgba(63,125,98,.22)\':\'rgba(125,186,152,.22)\');g.addColorStop(1,\'rgba(0,0,0,0)\');c.fillStyle=g;c.fillRect(0,0,W,H);\n  // ring paths\n  rings.forEach(function(R,ri){c.beginPath();for(var k=0;k<=72;k++){var q=P(ri,k/72*R.n);k?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y)}c.strokeStyle=cols[ri];c.globalAlpha=.22;c.lineWidth=1.2;c.stroke();c.globalAlpha=1});\n  // links + pulses\n  links.forEach(function(L){var a=P(L[0],L[1]),b=P(L[2],L[3]);var mxp=(a.x+b.x)/2+(cx-(a.x+b.x)/2)*.45,myp=(a.y+b.y)/2+(cy-(a.y+b.y)/2)*.45;\n   c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo(mxp,myp,b.x,b.y);c.strokeStyle=cols[L[0]];c.globalAlpha=.16;c.lineWidth=1;c.stroke();\n   var u=(t*.22+L[4])%1,ix=(1-u)*(1-u)*a.x+2*(1-u)*u*mxp+u*u*b.x,iy=(1-u)*(1-u)*a.y+2*(1-u)*u*myp+u*u*b.y;\n   c.globalAlpha=Math.sin(u*Math.PI)*.95;c.fillStyle=cols[L[2]];c.beginPath();c.arc(ix,iy,2.2,0,7);c.fill();c.globalAlpha=1});\n  // nodes depth-sorted\n  var all=[];rings.forEach(function(R,ri){for(var k=0;k<R.n;k++){var q=P(ri,k);q.ri=ri;all.push(q)}});all.sort(function(a,b){return b.z-a.z});\n  all.forEach(function(q){var r=(q.ri==0?3.6:q.ri==1?2.6:3.1)*q.p;c.globalAlpha=.35+.65*Math.max(0,Math.min(1,(1.2-q.z)/2));\n   c.fillStyle=cols[q.ri];c.beginPath();c.arc(q.x,q.y,r,0,7);c.fill();\n   if(q.ri==0){c.strokeStyle=cols[0];c.globalAlpha*=.35;c.beginPath();c.arc(q.x,q.y,r*2.2,0,7);c.stroke()}c.globalAlpha=1});\n })}\nwindow.FR_orbit=orbit;\nfunction visual(cap){var v=document.createElement(\'div\');v.className=\'sk-visual\';v.innerHTML=\'<canvas aria-hidden="true"></canvas><div class="sk-caption">\'+cap+\'</div><div class="sk-legend"><span><i style="background:var(--fw1)"></i>NIST CSF 2.0</span><span><i style="background:var(--fw2)"></i>SP 800-53 Rev.5</span><span><i style="background:var(--fw3)"></i>ISO/IEC 27002</span></div>\';return v}\nvar hero=document.querySelector(\'.pagein > .stage-hero\');\nif(hero){var box=document.createElement(\'section\');box.className=\'sk-hero\';var left=document.createElement(\'div\');left.className=\'sk-stagger\';\n hero.parentNode.insertBefore(box,hero);[hero,hero.parentNode.querySelector(\'form.seek\'),hero.parentNode.querySelector(\'.quick-chips\'),box.nextElementSibling&&box.parentNode.querySelector(\':scope > p.note\')].forEach(function(e,i){if(e){e.style.setProperty(\'--i\',i);left.appendChild(e)}});\n var v=visual(\'Official crosswalk · live\');box.appendChild(left);box.appendChild(v);orbit(v.querySelector(\'canvas\'))}\nvar auth=document.querySelector(\'.pagein > .auth\');\nif(auth){var lg=document.createElement(\'section\');lg.className=\'sk-login\';auth.parentNode.insertBefore(lg,auth);var v2=visual(\'Framework Reader\');lg.appendChild(v2);lg.appendChild(auth);orbit(v2.querySelector(\'canvas\'))}\n})();\n'


def head() -> str:
    return _MOTION_BOOT + (f"<script>{HEAD_JS}</script>" if HEAD_JS else "")


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    return ""


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* control page: action cards without colored top bars, wider reading */\n.doing .claim::before,.doing .chat::before{display:none!important}\n.doing .claim,.doing .chat{border-color:transparent!important;border-radius:22px}\n.split{grid-template-columns:minmax(0,1fr) clamp(20rem,24vw,26rem);gap:clamp(1.5rem,3vw,3.5rem)}\n.doc p,.doc ul,.doc ol{max-width:86ch}\n.doing .claim button{border:0!important;color:#fff!important;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 85%,#fff),var(--accent-strong))!important}\n:root:not([data-theme="light"]) .doing .claim button{background:linear-gradient(180deg,#4C8E70,var(--green))!important}\n.graph-viewport{border-color:transparent!important;box-shadow:var(--card-shadow)}\n/* progress bars stay thin; framework cards stretch to fill the row */\n.bar{display:block;height:6px!important;border-radius:6px;margin-top:1rem}\n.bar i{height:100%!important}\n.pagein > .cards{grid-template-columns:repeat(auto-fit,minmax(22rem,1fr))}\n.pagein > .cards .card{min-height:9.5rem;padding:1.6rem 1.7rem}\n/* ===== A · Crosswalk Atlas ===== */\n.top{gap:1.4rem;padding-top:1rem!important;padding-bottom:1rem!important;margin-bottom:1.6rem;\n  box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.35rem;font-weight:700}\n.top h1 a::before{content:"";display:inline-block;width:1.6rem;height:1.6rem;margin-right:.6rem;vertical-align:-.35rem;\n  background:conic-gradient(from 210deg,var(--fw1),var(--fw2),var(--fw3),var(--fw1));border-radius:50%;\n  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);\n  animation:aSpin 14s linear infinite}\n@keyframes aSpin{to{transform:rotate(360deg)}}\n.topnav{font-size:.98rem;padding:.6rem 1.1rem;color:var(--body);position:relative}\n.topnav::after{content:"";position:absolute;left:1.1rem;right:1.1rem;bottom:.3rem;height:2px;border-radius:2px;\n  background:linear-gradient(90deg,var(--fw1),var(--fw2));transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}\n.topnav:hover{background:var(--surface-high)}.topnav:hover::after{transform:scaleX(1)}\n.topright{margin-left:auto}\n.sk-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(1.5rem,3vw,4rem);align-items:center;\n  min-height:min(64vh,640px);margin:0 0 1.5rem}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.6rem}\n.sk-hero .stage-headline{font-size:clamp(2.2rem,4vw,3.6rem);line-height:1.08;letter-spacing:-.035em}\n.sk-hero .stage-sub{margin:0 0 .5rem;max-width:40rem}\n.sk-hero form.seek{margin:0 0 1rem;max-width:none;padding:.5rem .55rem .5rem 1.4rem}\n.sk-hero form.seek input[type=search]{font-size:1.1rem;padding:.85rem .5rem}\n.sk-hero form.seek button{padding:.85rem 1.9rem;font-size:1rem}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0 .6rem}\n.sk-hero .note{text-align:left!important;margin:0}\n.sk-visual{position:relative;height:min(60vh,600px);border-radius:28px;overflow:hidden;\n  background:radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--accent) 12%,var(--surface)),var(--surface) 70%);\n  box-shadow:var(--card-shadow)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-legend{position:absolute;left:1.2rem;bottom:1rem;display:flex;gap:.6rem;flex-wrap:wrap;z-index:2}\n.sk-legend span{font-size:.8rem;font-weight:600;padding:.3rem .75rem;border-radius:980px;background:color-mix(in srgb,var(--surface) 78%,transparent);\n  backdrop-filter:blur(8px);color:var(--ink);display:inline-flex;align-items:center;gap:.45rem}\n.sk-legend i{width:.6rem;height:.6rem;border-radius:50%;display:inline-block}\n.sk-caption{position:absolute;right:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);z-index:2}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:1rem 0 2rem}\n.stat-card{text-align:left;padding:1.6rem 1.6rem;border-radius:22px;position:relative;overflow:hidden}\n.stat-card::before{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:160%;\n  background:radial-gradient(circle,color-mix(in srgb,var(--accent) 8%,transparent),transparent 65%);transition:transform .6s var(--ease)}\n.stat-card:hover::before{transform:translate(-12%,12%)}\n.stat-num{font-size:2.6rem;letter-spacing:-.03em}\n.stat-desc{color:var(--muted);letter-spacing:.1em}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;gap:2rem}\n.cards{grid-template-columns:repeat(auto-fill,minmax(17rem,1fr))}\n.card{border-radius:20px;padding:1.45rem 1.55rem}\n.card:hover{transform:translateY(-4px) rotateX(2deg)}\n.card .id{font-size:.82rem;color:var(--accent)}\n.card h3{font-size:1.1rem}\nh2{font-size:1.5rem}\n.hud-card{border-radius:22px}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n/* login: split */\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{height:min(72vh,680px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}\n.sk-login .auth form{padding:2rem 2rem;border-radius:24px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
HEAD_JS = '(function(){var r=document.documentElement;try{if(!localStorage.getItem("fr-theme")&&matchMedia("(prefers-color-scheme: light)").matches)r.dataset.theme="light"}catch(e){}\nvar light=r.dataset.theme==="light";\nwindow.FR_FW_COLORS=light?{"NIST-CSF-2.0":"#5C7F99","NIST-800-53-R5":"#7E9A7A","ISO-27002-2022":"#B08F55"}:{"NIST-CSF-2.0":"#8FB0C6","NIST-800-53-R5":"#9DB89A","ISO-27002-2022":"#CDB487"};\nwindow.FR_ACCENT=light?"#3F7D62":"#7DBA98";})();\n'
TAIL_JS = '(function(){\nvar R=document.documentElement;function motion(){return !R.classList.contains(\'motion-off\')}\nwindow.FR_motion=motion;\n// recolor graph chips to calm palette\ndocument.querySelectorAll(\'.framework-chips .chip[data-fid]\').forEach(function(c){var col=(window.FR_FW_COLORS||{})[c.dataset.fid];if(col){c.style.color=col;var d=c.querySelector(\'.chip-dot\');if(d)d.style.background=col}});\n// stagger groups\ndocument.querySelectorAll(\'.stage-stats,.cards,.hud-stat-list\').forEach(function(g){g.classList.add(\'sk-stagger\');Array.from(g.children).forEach(function(c,i){c.style.setProperty(\'--i\',i)})});\n// count-up\ndocument.querySelectorAll(\'.stat-num\').forEach(function(el){var m=el.textContent.match(/^([\\d,]+)(.*)$/);if(!m||!motion())return;var to=parseInt(m[1].replace(/,/g,\'\'),10),suf=m[2],t0=null;\n function f(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString(\'en-US\')+suf;if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});\n// shared canvas helper\nwindow.FR_canvas=function(cv,draw){var ctx=cv.getContext(\'2d\'),W=0,H=0,dpr=Math.min(2,devicePixelRatio||1),mx=0,my=0,t0=performance.now();\n function size(){var b=cv.getBoundingClientRect();W=b.width;H=b.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}\n size();new ResizeObserver(size).observe(cv);\n addEventListener(\'pointermove\',function(e){var b=cv.getBoundingClientRect();mx=((e.clientX-b.left)/b.width-.5);my=((e.clientY-b.top)/b.height-.5)},{passive:true});\n function css(n){return getComputedStyle(R).getPropertyValue(n).trim()}\n var last=0;function loop(now){var t=motion()?(now-t0)/1000:last;last=t;ctx.clearRect(0,0,W,H);draw(ctx,W,H,t,mx,my,css,R.dataset.theme===\'light\');requestAnimationFrame(loop)}\n requestAnimationFrame(loop)};\n})();\n(function(){\nfunction orbit(cv){var rings=[{n:22,r:.92,tilt:1.2,roll:0,ph:0,col:\'--fw1\',name:\'CSF\'},{n:40,r:.7,tilt:1.1,roll:1.05,ph:1.7,col:\'--fw2\',name:\'800-53\'},{n:30,r:.48,tilt:1.0,roll:-1.05,ph:3.1,col:\'--fw3\',name:\'ISO\'}];\n var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647}\n var links=[];for(var i=0;i<46;i++){var a=Math.floor(rnd()*3),b=(a+1+Math.floor(rnd()*2))%3;links.push([a,Math.floor(rnd()*rings[a].n),b,Math.floor(rnd()*rings[b].n),rnd()])}\n FR_canvas(cv,function(c,W,H,t,mx,my,css,light){var S=Math.min(W,H)*.46,cx=W/2+mx*18,cy=H/2+my*14,ry=t*.18+mx*.6,rx=-.35+my*.4;\n  function P(ring,k){var R=rings[ring],a=k/R.n*Math.PI*2+R.ph+t*.05*(ring%2?-1:1),x=Math.cos(a)*R.r,y=0,z=Math.sin(a)*R.r;\n   var ct=Math.cos(R.tilt),st=Math.sin(R.tilt);var y2=y*ct-z*st,z2=y*st+z*ct;y=y2;z=z2;var c0=Math.cos(R.roll),s0=Math.sin(R.roll),xr=x*c0-y*s0;y=x*s0+y*c0;x=xr;\n   var cr=Math.cos(ry),sr=Math.sin(ry);var x3=x*cr+z*sr,z3=-x*sr+z*cr;var cxr=Math.cos(rx),sxr=Math.sin(rx);var y4=y*cxr-z3*sxr,z4=y*sxr+z3*cxr;\n   var p=2.6/(2.6+z4);return {x:cx+x3*S*p,y:cy+y4*S*p,z:z4,p:p}}\n  var cols=rings.map(function(r){return css(r.col)});\n  // core glow\n  var g=c.createRadialGradient(cx,cy,0,cx,cy,S*.5);g.addColorStop(0,light?\'rgba(63,125,98,.22)\':\'rgba(125,186,152,.22)\');g.addColorStop(1,\'rgba(0,0,0,0)\');c.fillStyle=g;c.fillRect(0,0,W,H);\n  // ring paths\n  rings.forEach(function(R,ri){c.beginPath();for(var k=0;k<=72;k++){var q=P(ri,k/72*R.n);k?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y)}c.strokeStyle=cols[ri];c.globalAlpha=.22;c.lineWidth=1.2;c.stroke();c.globalAlpha=1});\n  // links + pulses\n  links.forEach(function(L){var a=P(L[0],L[1]),b=P(L[2],L[3]);var mxp=(a.x+b.x)/2+(cx-(a.x+b.x)/2)*.45,myp=(a.y+b.y)/2+(cy-(a.y+b.y)/2)*.45;\n   c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo(mxp,myp,b.x,b.y);c.strokeStyle=cols[L[0]];c.globalAlpha=.16;c.lineWidth=1;c.stroke();\n   var u=(t*.22+L[4])%1,ix=(1-u)*(1-u)*a.x+2*(1-u)*u*mxp+u*u*b.x,iy=(1-u)*(1-u)*a.y+2*(1-u)*u*myp+u*u*b.y;\n   c.globalAlpha=Math.sin(u*Math.PI)*.95;c.fillStyle=cols[L[2]];c.beginPath();c.arc(ix,iy,2.2,0,7);c.fill();c.globalAlpha=1});\n  // nodes depth-sorted\n  var all=[];rings.forEach(function(R,ri){for(var k=0;k<R.n;k++){var q=P(ri,k);q.ri=ri;all.push(q)}});all.sort(function(a,b){return b.z-a.z});\n  all.forEach(function(q){var r=(q.ri==0?3.6:q.ri==1?2.6:3.1)*q.p;c.globalAlpha=.35+.65*Math.max(0,Math.min(1,(1.2-q.z)/2));\n   c.fillStyle=cols[q.ri];c.beginPath();c.arc(q.x,q.y,r,0,7);c.fill();\n   if(q.ri==0){c.strokeStyle=cols[0];c.globalAlpha*=.35;c.beginPath();c.arc(q.x,q.y,r*2.2,0,7);c.stroke()}c.globalAlpha=1});\n })}\nwindow.FR_orbit=orbit;\nfunction visual(cap){var v=document.createElement(\'div\');v.className=\'sk-visual\';v.innerHTML=\'<canvas aria-hidden="true"></canvas><div class="sk-caption">\'+cap+\'</div><div class="sk-legend"><span><i style="background:var(--fw1)"></i>NIST CSF 2.0</span><span><i style="background:var(--fw2)"></i>SP 800-53 Rev.5</span><span><i style="background:var(--fw3)"></i>ISO/IEC 27002</span></div>\';return v}\nvar hero=document.querySelector(\'.pagein > .stage-hero\');\nif(hero){var box=document.createElement(\'section\');box.className=\'sk-hero\';var left=document.createElement(\'div\');left.className=\'sk-stagger\';\n hero.parentNode.insertBefore(box,hero);[hero,hero.parentNode.querySelector(\'form.seek\'),hero.parentNode.querySelector(\'.quick-chips\'),box.nextElementSibling&&box.parentNode.querySelector(\':scope > p.note\')].forEach(function(e,i){if(e){e.style.setProperty(\'--i\',i);left.appendChild(e)}});\n var v=visual(\'Official crosswalk · live\');box.appendChild(left);box.appendChild(v);orbit(v.querySelector(\'canvas\'))}\nvar auth=document.querySelector(\'.pagein > .auth\');\nif(auth){var lg=document.createElement(\'section\');lg.className=\'sk-login\';auth.parentNode.insertBefore(lg,auth);var v2=visual(\'Framework Reader\');lg.appendChild(v2);lg.appendChild(auth);orbit(v2.querySelector(\'canvas\'))}\n})();\n'


def head() -> str:
    return _MOTION_BOOT + (f"<script>{HEAD_JS}</script>" if HEAD_JS else "")


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    return ""


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
CSS = '/* ===== shared skin layer: calm palette, glow buttons, no thin borders ===== */\n:root{--fw1:#5C7F99;--fw2:#7E9A7A;--fw3:#B59A6A;--sage:#7E9A7A;--green:#3F7D62;\n  --g-blue:var(--fw1);--g-green:var(--fw2);--g-yellow:var(--fw3);--g-red:#B5706A;\n  --g-rainbow:linear-gradient(90deg,var(--fw1),var(--fw2),var(--fw3));\n  --gemini-gradient:linear-gradient(110deg,var(--accent) 0%,var(--sage) 55%,var(--fw3) 100%);\n  --ease:cubic-bezier(.2,.7,.2,1)}\n:root[data-theme="light"]{\n  --ground:#EEF2F1;--surface:#FFFFFF;--surface-high:#F5F8F7;--surface-highest:#E9EFED;\n  --sunk:#E7EDEB;--ink:#1F2A30;--body:#3A4750;--muted:#66767F;--rule:#DFE6E4;\n  --accent:#5C7F99;--accent-strong:#4A6B84;--accent-soft:#E2EBF0;--ask:#A65E57;\n  --success:#3F7D62;--success-soft:#E1EEE6;\n  --topbar-bg:rgba(238,242,241,.82);--topbar-line:transparent;--topglow:rgba(92,127,153,.14);\n  --row-hover:rgba(92,127,153,.05);--card-hover:#fff;--card-hover-line:transparent;\n  --selection:rgba(92,127,153,.25);\n  --card-shadow:0 1px 2px rgba(31,42,48,.04),0 6px 22px rgba(31,42,48,.06);\n  --card-shadow-hover:0 4px 10px rgba(31,42,48,.06),0 22px 48px rgba(63,90,110,.16);\n  --glow:rgba(92,127,153,.38)}\n:root:not([data-theme="light"]){\n  --ground:#1B1F23;--surface:#22272C;--surface-high:#2A3036;--surface-highest:#323940;\n  --sunk:#181B1F;--ink:#E9EDEB;--body:#C4CCC9;--muted:#8D9A97;--rule:#2E353B;\n  --accent:#8FB0C6;--accent-strong:#5C7F99;--accent-soft:#2A3843;--ask:#D7958D;\n  --success:#7DBA98;--success-soft:#21332A;\n  --fw1:#8FB0C6;--fw2:#9DB89A;--fw3:#CDB487;--sage:#9DB89A;\n  --topbar-bg:rgba(27,31,35,.82);--topbar-line:transparent;--topglow:rgba(143,176,198,.12);\n  --row-hover:rgba(255,255,255,.025);--card-hover:#262C32;--card-hover-line:transparent;\n  --selection:rgba(143,176,198,.3);\n  --card-shadow:0 1px 2px rgba(0,0,0,.25),0 10px 28px rgba(0,0,0,.28);\n  --card-shadow-hover:0 6px 14px rgba(0,0,0,.3),0 26px 60px rgba(0,0,0,.42);\n  --glow:rgba(63,125,98,.45)}\nbody{font-size:16.5px}\n.wrap,.wrap.wide{max-width:1760px;padding:0 clamp(1.25rem,2.6vw,3rem) 5rem}\n.top,.wrap.wide .top{padding:.85rem clamp(1.25rem,2.6vw,3rem);border-bottom:0}\n.top::after{display:none}\n.gemini-sparkle{color:var(--fw3)}\n/* no thin borders anywhere on boxes */\n.card,.stat-card,.hud-card,table,form,.empty-gap,form.seek,.chip,.callout,.mark,.tag,\n.keynote-pill,.stage-eyebrow,.signed,.draft,.shuffle-btn,.themebtn,textarea,\ninput[type=text],input[type=password],input[type=file],input[type=search],select{border-color:transparent!important}\nform.tiny{box-shadow:none;background:transparent}\n.card::after{display:none}\n.card::before{background:radial-gradient(28rem circle at var(--mx,50%) var(--my,50%),\n  color-mix(in srgb,var(--accent) 16%,transparent),transparent 62%)}\n/* left accent bars -> soft tinted blocks */\n.daily-card .snippet,.doc p.own{border-left:0!important;border-radius:12px!important;padding:.7rem .95rem!important}\n.err{border-left:0;border-radius:14px;background:color-mix(in srgb,var(--ask) 12%,var(--surface))}\n.aurora i:nth-child(1){background:radial-gradient(circle,var(--fw1),transparent 65%)}\n.aurora i:nth-child(2){background:radial-gradient(circle,var(--fw2),transparent 65%)}\n.aurora i:nth-child(3){background:radial-gradient(circle,var(--green),transparent 65%)}\n.aurora i:nth-child(4){background:radial-gradient(circle,var(--fw3),transparent 65%)}\n.aurora i{opacity:.14}:root[data-theme="light"] .aurora i{opacity:.16}\n/* buttons: glow + shine sweep, press 97%, keyboard-only focus ring */\nbutton,a.cta,form.seek button{border:0!important;color:#fff;font-weight:600;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 88%,#fff),var(--accent-strong));\n  box-shadow:0 1px 0 rgba(255,255,255,.18) inset,0 6px 18px -4px var(--glow);\n  transition:transform .18s var(--ease),box-shadow .25s var(--ease),filter .2s}\n:root:not([data-theme="light"]) button,:root:not([data-theme="light"]) a.cta,\n:root:not([data-theme="light"]) form.seek button{\n  background:linear-gradient(180deg,#4C8E70,var(--green))}\nbutton:hover,a.cta:hover,form.seek button:hover{opacity:1;filter:brightness(1.06);transform:translateY(-1px);\n  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 10px 28px -4px var(--glow),0 0 0 4px color-mix(in srgb,var(--glow) 35%,transparent)}\nbutton:active,a.cta:active{transform:scale(.97)}\nbutton:focus{outline:none}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\nbutton::after,a.cta::after{background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent)}\n.themebtn,.motionbtn,.shuffle-btn,form.tiny button.shuffle-btn{background:var(--surface-high)!important;color:var(--ink)!important;\n  box-shadow:var(--card-shadow)!important}\n.motionbtn{display:inline-flex;align-items:center;justify-content:center;padding:.45rem .6rem;border-radius:980px;margin-left:.2rem}\n.themebtn svg,.motionbtn svg{width:1.15rem;height:1.15rem;display:block}\n.motionbtn[aria-pressed="false"]{opacity:.55}\n.motionbtn[aria-pressed="true"] svg{color:var(--fw3)}\n/* inputs */\ntextarea,input[type=text],input[type=password],input[type=file]{background:var(--sunk);border-radius:12px}\ninput[type=password]{width:100%;padding:.65rem .85rem;font:inherit;color:var(--ink)}\nform.seek:focus-within{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 22%,transparent),0 14px 40px -8px var(--glow)}\n.chip{background:var(--surface-high);color:var(--body)}\n.chip:hover{background:var(--accent-soft);color:var(--ink)}\n.bar i,.hud-meter-fill{background:linear-gradient(90deg,var(--accent),var(--sage))}\ntable{border-collapse:separate}\ntd{border-bottom-color:color-mix(in srgb,var(--rule) 70%,transparent)}\n.tag.mine,.mark.mine{background:var(--success-soft);color:var(--success)}\n/* count-up + stagger */\n.stat-num{font-variant-numeric:tabular-nums}\n@keyframes skRise{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\n.sk-stagger>*{animation:skRise .7s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}\n/* control page: action cards without colored top bars, wider reading */\n.doing .claim::before,.doing .chat::before{display:none!important}\n.doing .claim,.doing .chat{border-color:transparent!important;border-radius:22px}\n.split{grid-template-columns:minmax(0,1fr) clamp(20rem,24vw,26rem);gap:clamp(1.5rem,3vw,3.5rem)}\n.doc p,.doc ul,.doc ol{max-width:86ch}\n.doing .claim button{border:0!important;color:#fff!important;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--accent-strong) 85%,#fff),var(--accent-strong))!important}\n:root:not([data-theme="light"]) .doing .claim button{background:linear-gradient(180deg,#4C8E70,var(--green))!important}\n.graph-viewport{border-color:transparent!important;box-shadow:var(--card-shadow)}\n/* progress bars stay thin; framework cards stretch to fill the row */\n.bar{display:block;height:6px!important;border-radius:6px;margin-top:1rem}\n.bar i{height:100%!important}\n.pagein > .cards{grid-template-columns:repeat(auto-fit,minmax(22rem,1fr))}\n.pagein > .cards .card{min-height:9.5rem;padding:1.6rem 1.7rem}\n/* ===== A · Crosswalk Atlas ===== */\n.top{gap:1.4rem;padding-top:1rem!important;padding-bottom:1rem!important;margin-bottom:1.6rem;\n  box-shadow:0 1px 0 color-mix(in srgb,var(--ink) 6%,transparent)}\n.top h1{font-size:1.35rem;font-weight:700}\n.top h1 a::before{content:"";display:inline-block;width:1.6rem;height:1.6rem;margin-right:.6rem;vertical-align:-.35rem;\n  background:conic-gradient(from 210deg,var(--fw1),var(--fw2),var(--fw3),var(--fw1));border-radius:50%;\n  -webkit-mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);mask:radial-gradient(circle,transparent 38%,#000 40% 58%,transparent 60% 70%,#000 72%);\n  animation:aSpin 14s linear infinite}\n@keyframes aSpin{to{transform:rotate(360deg)}}\n.topnav{font-size:.98rem;padding:.6rem 1.1rem;color:var(--body);position:relative}\n.topnav::after{content:"";position:absolute;left:1.1rem;right:1.1rem;bottom:.3rem;height:2px;border-radius:2px;\n  background:linear-gradient(90deg,var(--fw1),var(--fw2));transform:scaleX(0);transform-origin:left;transition:transform .35s var(--ease)}\n.topnav:hover{background:var(--surface-high)}.topnav:hover::after{transform:scaleX(1)}\n.topright{margin-left:auto}\n.sk-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(1.5rem,3vw,4rem);align-items:center;\n  min-height:min(64vh,640px);margin:0 0 1.5rem}\n.sk-hero .stage-hero{text-align:left;margin:0 0 1.6rem}\n.sk-hero .stage-headline{font-size:clamp(2.2rem,4vw,3.6rem);line-height:1.08;letter-spacing:-.035em}\n.sk-hero .stage-sub{margin:0 0 .5rem;max-width:40rem}\n.sk-hero form.seek{margin:0 0 1rem;max-width:none;padding:.5rem .55rem .5rem 1.4rem}\n.sk-hero form.seek input[type=search]{font-size:1.1rem;padding:.85rem .5rem}\n.sk-hero form.seek button{padding:.85rem 1.9rem;font-size:1rem}\n.sk-hero .quick-chips{justify-content:flex-start;margin:.4rem 0 .6rem}\n.sk-hero .note{text-align:left!important;margin:0}\n.sk-visual{position:relative;height:min(60vh,600px);border-radius:28px;overflow:hidden;\n  background:radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--accent) 12%,var(--surface)),var(--surface) 70%);\n  box-shadow:var(--card-shadow)}\n.sk-visual canvas{position:absolute;inset:0;width:100%;height:100%}\n.sk-legend{position:absolute;left:1.2rem;bottom:1rem;display:flex;gap:.6rem;flex-wrap:wrap;z-index:2}\n.sk-legend span{font-size:.8rem;font-weight:600;padding:.3rem .75rem;border-radius:980px;background:color-mix(in srgb,var(--surface) 78%,transparent);\n  backdrop-filter:blur(8px);color:var(--ink);display:inline-flex;align-items:center;gap:.45rem}\n.sk-legend i{width:.6rem;height:.6rem;border-radius:50%;display:inline-block}\n.sk-caption{position:absolute;right:1.3rem;top:1.1rem;font:600 .72rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);z-index:2}\n.stage-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2rem;margin:1rem 0 2rem}\n.stat-card{text-align:left;padding:1.6rem 1.6rem;border-radius:22px;position:relative;overflow:hidden}\n.stat-card::before{content:"";position:absolute;right:-30%;top:-60%;width:80%;height:160%;\n  background:radial-gradient(circle,color-mix(in srgb,var(--accent) 8%,transparent),transparent 65%);transition:transform .6s var(--ease)}\n.stat-card:hover::before{transform:translate(-12%,12%)}\n.stat-num{font-size:2.6rem;letter-spacing:-.03em}\n.stat-desc{color:var(--muted);letter-spacing:.1em}\n.bento-layout{grid-template-columns:minmax(0,1fr) 380px;gap:2rem}\n.cards{grid-template-columns:repeat(auto-fill,minmax(17rem,1fr))}\n.card{border-radius:20px;padding:1.45rem 1.55rem}\n.card:hover{transform:translateY(-4px) rotateX(2deg)}\n.card .id{font-size:.82rem;color:var(--accent)}\n.card h3{font-size:1.1rem}\nh2{font-size:1.5rem}\n.hud-card{border-radius:22px}\n@media (max-width:1100px){.sk-hero{grid-template-columns:1fr}.stage-stats{grid-template-columns:repeat(2,1fr)}}\n/* login: split */\n.sk-login{display:grid;grid-template-columns:1.2fr 1fr;gap:3rem;align-items:center;min-height:calc(100vh - 9rem)}\n.sk-login .sk-visual{height:min(72vh,680px)}\n.sk-login .auth{max-width:30rem;width:100%;margin:0 auto}\n.sk-login .auth form{padding:2rem 2rem;border-radius:24px}\n.sk-login .auth h2{font-size:2rem;margin-top:0}\n'
HEAD_JS = '(function(){var r=document.documentElement;try{if(!localStorage.getItem("fr-theme")&&matchMedia("(prefers-color-scheme: light)").matches)r.dataset.theme="light"}catch(e){}\nvar light=r.dataset.theme==="light",n="NIST-",c=light?["#5C7F99","#7E9A7A","#B08F55"]:["#8FB0C6","#9DB89A","#CDB487"],m={};\nm[n+"CSF-2.0"]=c[0];m[n+"800-53-R5"]=c[1];m["ISO-"+"27002-2022"]=c[2];window.FR_FW_COLORS=m;\nwindow.FR_ACCENT=light?"#3F7D62":"#7DBA98";})();\n'
TAIL_JS = '(function(){\nvar R=document.documentElement;function motion(){return !R.classList.contains(\'motion-off\')}\nwindow.FR_motion=motion;\n// recolor graph chips to calm palette\ndocument.querySelectorAll(\'.framework-chips .chip[data-fid]\').forEach(function(c){var col=(window.FR_FW_COLORS||{})[c.dataset.fid];if(col){c.style.color=col;var d=c.querySelector(\'.chip-dot\');if(d)d.style.background=col}});\n// stagger groups\ndocument.querySelectorAll(\'.stage-stats,.cards,.hud-stat-list\').forEach(function(g){g.classList.add(\'sk-stagger\');Array.from(g.children).forEach(function(c,i){c.style.setProperty(\'--i\',i)})});\n// count-up\ndocument.querySelectorAll(\'.stat-num\').forEach(function(el){var m=el.textContent.match(/^([\\d,]+)(.*)$/);if(!m||!motion())return;var to=parseInt(m[1].replace(/,/g,\'\'),10),suf=m[2],t0=null;\n function f(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/1400),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString(\'en-US\')+suf;if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)});\n// shared canvas helper\nwindow.FR_canvas=function(cv,draw){var ctx=cv.getContext(\'2d\'),W=0,H=0,dpr=Math.min(2,devicePixelRatio||1),mx=0,my=0,t0=performance.now();\n function size(){var b=cv.getBoundingClientRect();W=b.width;H=b.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}\n size();new ResizeObserver(size).observe(cv);\n addEventListener(\'pointermove\',function(e){var b=cv.getBoundingClientRect();mx=((e.clientX-b.left)/b.width-.5);my=((e.clientY-b.top)/b.height-.5)},{passive:true});\n function css(n){return getComputedStyle(R).getPropertyValue(n).trim()}\n var last=0;function loop(now){var t=motion()?(now-t0)/1000:last;last=t;ctx.clearRect(0,0,W,H);draw(ctx,W,H,t,mx,my,css,R.dataset.theme===\'light\');requestAnimationFrame(loop)}\n requestAnimationFrame(loop)};\n})();\n(function(){\nfunction orbit(cv){var rings=[{n:22,r:.92,tilt:1.2,roll:0,ph:0,col:\'--fw1\',name:\'CSF\'},{n:40,r:.7,tilt:1.1,roll:1.05,ph:1.7,col:\'--fw2\',name:\'800-53\'},{n:30,r:.48,tilt:1.0,roll:-1.05,ph:3.1,col:\'--fw3\',name:\'ISO\'}];\n var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647}\n var links=[];for(var i=0;i<46;i++){var a=Math.floor(rnd()*3),b=(a+1+Math.floor(rnd()*2))%3;links.push([a,Math.floor(rnd()*rings[a].n),b,Math.floor(rnd()*rings[b].n),rnd()])}\n FR_canvas(cv,function(c,W,H,t,mx,my,css,light){var S=Math.min(W,H)*.46,cx=W/2+mx*18,cy=H/2+my*14,ry=t*.18+mx*.6,rx=-.35+my*.4;\n  function P(ring,k){var R=rings[ring],a=k/R.n*Math.PI*2+R.ph+t*.05*(ring%2?-1:1),x=Math.cos(a)*R.r,y=0,z=Math.sin(a)*R.r;\n   var ct=Math.cos(R.tilt),st=Math.sin(R.tilt);var y2=y*ct-z*st,z2=y*st+z*ct;y=y2;z=z2;var c0=Math.cos(R.roll),s0=Math.sin(R.roll),xr=x*c0-y*s0;y=x*s0+y*c0;x=xr;\n   var cr=Math.cos(ry),sr=Math.sin(ry);var x3=x*cr+z*sr,z3=-x*sr+z*cr;var cxr=Math.cos(rx),sxr=Math.sin(rx);var y4=y*cxr-z3*sxr,z4=y*sxr+z3*cxr;\n   var p=2.6/(2.6+z4);return {x:cx+x3*S*p,y:cy+y4*S*p,z:z4,p:p}}\n  var cols=rings.map(function(r){return css(r.col)});\n  // core glow\n  var g=c.createRadialGradient(cx,cy,0,cx,cy,S*.5);g.addColorStop(0,light?\'rgba(63,125,98,.22)\':\'rgba(125,186,152,.22)\');g.addColorStop(1,\'rgba(0,0,0,0)\');c.fillStyle=g;c.fillRect(0,0,W,H);\n  // ring paths\n  rings.forEach(function(R,ri){c.beginPath();for(var k=0;k<=72;k++){var q=P(ri,k/72*R.n);k?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y)}c.strokeStyle=cols[ri];c.globalAlpha=.22;c.lineWidth=1.2;c.stroke();c.globalAlpha=1});\n  // links + pulses\n  links.forEach(function(L){var a=P(L[0],L[1]),b=P(L[2],L[3]);var mxp=(a.x+b.x)/2+(cx-(a.x+b.x)/2)*.45,myp=(a.y+b.y)/2+(cy-(a.y+b.y)/2)*.45;\n   c.beginPath();c.moveTo(a.x,a.y);c.quadraticCurveTo(mxp,myp,b.x,b.y);c.strokeStyle=cols[L[0]];c.globalAlpha=.16;c.lineWidth=1;c.stroke();\n   var u=(t*.22+L[4])%1,ix=(1-u)*(1-u)*a.x+2*(1-u)*u*mxp+u*u*b.x,iy=(1-u)*(1-u)*a.y+2*(1-u)*u*myp+u*u*b.y;\n   c.globalAlpha=Math.sin(u*Math.PI)*.95;c.fillStyle=cols[L[2]];c.beginPath();c.arc(ix,iy,2.2,0,7);c.fill();c.globalAlpha=1});\n  // nodes depth-sorted\n  var all=[];rings.forEach(function(R,ri){for(var k=0;k<R.n;k++){var q=P(ri,k);q.ri=ri;all.push(q)}});all.sort(function(a,b){return b.z-a.z});\n  all.forEach(function(q){var r=(q.ri==0?3.6:q.ri==1?2.6:3.1)*q.p;c.globalAlpha=.35+.65*Math.max(0,Math.min(1,(1.2-q.z)/2));\n   c.fillStyle=cols[q.ri];c.beginPath();c.arc(q.x,q.y,r,0,7);c.fill();\n   if(q.ri==0){c.strokeStyle=cols[0];c.globalAlpha*=.35;c.beginPath();c.arc(q.x,q.y,r*2.2,0,7);c.stroke()}c.globalAlpha=1});\n })}\nwindow.FR_orbit=orbit;\nfunction visual(cap){var v=document.createElement(\'div\');v.className=\'sk-visual\';v.innerHTML=\'<canvas aria-hidden="true"></canvas><div class="sk-caption">\'+cap+\'</div><div class="sk-legend"><span><i style="background:var(--fw1)"></i>NIST CSF 2.0</span><span><i style="background:var(--fw2)"></i>SP 800-53 Rev.5</span><span><i style="background:var(--fw3)"></i>ISO/IEC 27002</span></div>\';return v}\nvar hero=document.querySelector(\'.pagein > .stage-hero\');\nif(hero){var box=document.createElement(\'section\');box.className=\'sk-hero\';var left=document.createElement(\'div\');left.className=\'sk-stagger\';\n hero.parentNode.insertBefore(box,hero);[hero,hero.parentNode.querySelector(\'form.seek\'),hero.parentNode.querySelector(\'.quick-chips\'),box.nextElementSibling&&box.parentNode.querySelector(\':scope > p.note\')].forEach(function(e,i){if(e){e.style.setProperty(\'--i\',i);left.appendChild(e)}});\n var v=visual(\'Official crosswalk · live\');box.appendChild(left);box.appendChild(v);orbit(v.querySelector(\'canvas\'))}\nvar auth=document.querySelector(\'.pagein > .auth\');\nif(auth){var lg=document.createElement(\'section\');lg.className=\'sk-login\';auth.parentNode.insertBefore(lg,auth);var v2=visual(\'Framework Reader\');lg.appendChild(v2);lg.appendChild(auth);orbit(v2.querySelector(\'canvas\'))}\n})();\n'


def head() -> str:
    return _MOTION_BOOT + (f"<script>{HEAD_JS}</script>" if HEAD_JS else "")


def chrome(*, bare: bool, may: Callable[[str], bool], who: str, title: str) -> str:
    return ""


def tail() -> str:
    return (f"<style>{CSS}</style>" if CSS else "") + (
        f"<script>{TAIL_JS}</script>" if TAIL_JS else "")
